    tldr: "Gynaecologic oncologist and immunotherapy researcher who directs the University of Chicago Medicine Comprehensive Cancer Center.",
    summary: "Kunle Odunsi, MD, PhD, is Director of the University of Chicago Medicine Comprehensive Cancer Center, an NCI-designated comprehensive cancer centre. A gynaecologic oncologist, his research focuses on immunotherapy and vaccine therapy for cancer, particularly ovarian cancer, including NY-ESO-1 targeted vaccines and adoptive T-cell approaches. His role is listed on the centre's leadership page.",
    profiles: [{ label: "Institution profile", url: "https://www.uchicagomedicine.org/cancer/about-us/leadership" }, { label: "PubMed", url: "https://pubmed.ncbi.nlm.nih.gov/?term=Odunsi+K%5BAuthor%5D" }],
    tags: ["leadership", "clinician-scientist", "immunotherapy", "ovarian cancer"], cancers: ["ovarian"],
