    tldr: "Pancreatic cancer surgeon-scientist who directs UC San Diego Moores Cancer Center, an NCI-designated comprehensive cancer center.",
    summary: "Diane M. Simeone, MD, is Director of UC San Diego Moores Cancer Center and Professor of Surgery and Pharmacology. She is a surgical oncologist and pancreatic cancer researcher whose work spans pancreatic cancer stem cells, early detection in high-risk individuals and the Precision Promise adaptive platform trial. She previously directed the Pancreatic Cancer Center at NYU Langone.",
    profiles: [{ label: "Institution profile", url: "https://moorescancercenter.ucsd.edu/about/leadership/" }, { label: "PubMed", url: "https://pubmed.ncbi.nlm.nih.gov/?term=Simeone+DM%5BAuthor%5D" }],
