    tldr: "Cancer pharmacologist at UC San Diego known for work on G-protein signalling and mTOR-targeted therapy in head and neck cancer.",
    summary: "J. Silvio Gutkind, PhD, is Associate Director for Basic Science at UC San Diego Moores Cancer Center and Chair of the Department of Pharmacology. His laboratory studies G-protein-coupled receptor and PI3K/mTOR signalling in cancer, translating these findings into clinical trials of mTOR inhibitors and immunotherapy combinations in head and neck squamous cell carcinoma.",
    profiles: [{ label: "Institution profile", url: "https://moorescancercenter.ucsd.edu/about/leadership/" }, { label: "PubMed", url: "https://pubmed.ncbi.nlm.nih.gov/?term=Gutkind+JS%5BAuthor%5D" }],
    tags: ["clinician-scientist", "head and neck cancer", "signalling"], cancers: ["head-and-neck"],
